<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Database;Auth::requireAdmin();$rows=Database::connection()->query("SELECT r.id,r.round_type,r.division,r.status,e.name event_name,e.event_date FROM bdc_test_scoring_rounds r JOIN bdc_test_events e ON e.id=r.event_id WHERE r.status NOT IN('completed','archived') ORDER BY e.event_date DESC,e.name,r.division,FIELD(r.round_type,'heats','semifinal','final'),r.id")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Test Live Screen Projector</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f4f6f9}.card{border-radius:16px}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../scoring-tests/select-mode.php">Scoring Tests</a><a class="btn btn-light btn-sm" href="../">Dashboard</a></div></nav><main class="container py-4"><div class="alert alert-warning fw-bold">TEST MODE · Projection data comes only from Scoring Tests.</div><h1 class="h2">Test Live Screen Projector</h1><p class="text-muted mb-4">Choose an active Test competition round.</p><div class="row g-3"><?php foreach($rows as $r):?><div class="col-lg-6"><div class="card shadow-sm h-100"><div class="card-body"><div class="d-flex justify-content-between"><div><h2 class="h5 mb-1"><?=e($r['event_name'])?></h2><div class="text-muted"><?=e(ucwords(str_replace('_',' ',$r['division'])))?></div></div><span class="badge text-bg-warning"><?=e(strtoupper($r['round_type']))?></span></div><a class="btn btn-danger w-100 mt-3" href="test-control.php?round_id=<?=(int)$r['id']?>">Projection Control</a></div></div></div><?php endforeach;?><?php if(!$rows):?><div class="alert alert-secondary">No active Test rounds.</div><?php endif;?></div></main></body></html>